const sumMemoryUsageSince = `-- name: SumMemoryUsageSince :many
SELECT purpose, CAST(SUM(calls) AS INTEGER) AS calls, CAST(SUM(input_tokens) AS INTEGER) AS input_tokens,
    CAST(SUM(output_tokens) AS INTEGER) AS output_tokens
FROM memory_usage WHERE hour >= ?1 GROUP BY purpose ORDER BY purpose
`

type SumMemoryUsageSinceRow struct {
	Purpose      string `json:"purpose"`
	Calls        int64  `json:"calls"`
	InputTokens  int64  `json:"inputTokens"`
	OutputTokens int64  `json:"outputTokens"`
}

func (q *Queries) SumMemoryUsageSince(ctx context.Context, since int64) ([]SumMemoryUsageSinceRow, error) {
	rows, err := q.db.QueryContext(ctx, sumMemoryUsageSince, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SumMemoryUsageSinceRow{}
	for rows.Next() {
		var i SumMemoryUsageSinceRow
		if err := rows.Scan(
			&i.Purpose,
			&i.Calls,
			&i.InputTokens,
			&i.OutputTokens,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

